341:         if ($state -isnot [System.Collections.IDictionary]) {
342:             $state = [ordered]@{}
343:         }
344: 
345:         $status = if ($state.Contains('status')) { [string]$state['status'] } else { '' }
346:         $cachedPath = if ($state.Contains('markerFilePath')) { [string]$state['markerFilePath'] } else { '' }
347:         $cachedWriteUtc = if ($state.Contains('markerLastWriteUtc')) { [string]$state['markerLastWriteUtc'] } else { '' }
