351:             $cachedPath -eq $snapshot.markerFilePath -and
352:             $cachedWriteUtc -eq $snapshot.markerLastWriteUtc -and
353:             -not [string]::IsNullOrWhiteSpace($cachedSessionId)) {
354:             return $true
